import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);

  const [streaming, setStreaming] = useState(false);
  const [capturedImage, setCapturedImage] = useState(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);

  // ================= CAMERA =================
  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ video: true });
      videoRef.current.srcObject = stream;
      setStreaming(true);
    } catch (err) {
      addNotification('Impossible d’accéder à la caméra', 'error');
    }
  };

  const stopCamera = () => {
    videoRef.current?.srcObject?.getTracks().forEach(track => track.stop());
    setStreaming(false);
  };

  // ================= CAPTURE =================
  const captureImage = () => {
    const canvas = canvasRef.current;
    const video = videoRef.current;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    canvas.getContext('2d').drawImage(video, 0, 0);

    const base64 = canvas.toDataURL('image/jpeg');
    setCapturedImage(base64);
    setResult(null);
  };

  // ================= RECOGNIZE =================
  const recognizeFace = async () => {
    if (!capturedImage) return;

    setLoading(true);
    setResult(null);

    try {
      const response = await attendanceAPI.recognize(capturedImage);

      if (response.success) {
        setResult({ status: 'success', data: response.data });
      } else if (response.isNoMatch) {
        setResult({ status: 'nomatch', data: response.data });
      } else {
        throw new Error(response.error);
      }
    } catch (err) {
      setResult({ status: 'error', error: err.message });
    }

    setLoading(false);
  };

  useEffect(() => {
    return () => stopCamera();
  }, []);

  return (
    <div style={styles.page}>

      {/* ================= NAVBAR EXISTANTE ================= */}
      <div style={styles.navbar}>
        <div style={styles.brand}>Attendance OS</div>

        <div style={styles.navLinks}>
          <span style={styles.link}>📊 Dashboard</span>
          <span style={styles.link}>➕ Enrôlement</span>
          <span style={{ ...styles.link, ...styles.active }}>📷 Reconnaissance</span>
        </div>

        <div style={styles.userSection}>
          <div style={styles.avatar}>👤</div>
          <div>
            <div style={styles.userId}>123456789</div>
            <div style={styles.userName}>Utilisateur</div>
          </div>
          <button style={styles.logout}>Déconnexion</button>
        </div>
      </div>

      {/* ================= HERO ================= */}
      <div style={styles.hero}>
        <img
          src="https://images.unsplash.com/photo-1555949963-aa79dcee981c"
          style={styles.heroImage}
        />
        <div style={styles.heroOverlay}>
          <h1 style={styles.heroTitle}>Reconnaissance faciale en temps réel</h1>
        </div>
      </div>

      {/* ================= MAIN ================= */}
      <div style={styles.container}>

        {/* CAMERA */}
        <div style={styles.card}>
          <video ref={videoRef} autoPlay style={styles.video} />
          <canvas ref={canvasRef} style={{ display: 'none' }} />
        </div>

        {/* CONTROLS */}
        <div style={styles.controls}>
          {!streaming ? (
            <button onClick={startCamera} style={styles.primaryBtn}>Démarrer</button>
          ) : (
            <button onClick={stopCamera} style={styles.dangerBtn}>Arrêter</button>
          )}

          <button onClick={captureImage} disabled={!streaming} style={styles.secondaryBtn}>
            Capturer
          </button>

          <button onClick={recognizeFace} disabled={!capturedImage || loading} style={styles.primaryBtn}>
            {loading ? 'Analyse...' : 'Reconnaître'}
          </button>

          {capturedImage && (
            <button onClick={() => setCapturedImage(null)} style={styles.secondaryBtn}>
              Réinitialiser
            </button>
          )}
        </div>

        {/* IMAGE */}
        {capturedImage && (
          <div style={styles.previewBox}>
            <img src={capturedImage} style={styles.preview} />
          </div>
        )}

        {/* RESULT */}
        {result && (
          <div style={styles.resultBox}>

            {result.status === 'success' && (
              <div style={styles.successCard}>
                <h3 style={styles.successTitle}>{result.data.student_name}</h3>

                <div style={styles.grid}>
                  <div><strong>Email:</strong> {result.data.email ?? "Non disponible"}</div>

                  <div><strong>Confiance:</strong> {
                    result.data.confidence
                      ? (result.data.confidence * 100).toFixed(1) + "%"
                      : "N/A"
                  }</div>

                  <div><strong>Heure:</strong> {
                    result.data.timestamp
                      ? new Date(result.data.timestamp.replace(" ", "T")).toLocaleString('fr-FR')
                      : "Non disponible"
                  }</div>

                  <div><strong>ID présence:</strong> {result.data.attendance_id ?? "N/A"}</div>

                  {/* ✅ CORRECTION */}
                  <div><strong>Embedding ID:</strong> {result.data.embedding_id ?? "N/A"}</div>
                </div>

                {result.data.photo_path && (
                  <img src={result.data.photo_path} style={styles.photo} />
                )}
              </div>
            )}

            {result.status === 'nomatch' && (
              <div style={styles.warningCard}>
                Aucun visage correspondant
              </div>
            )}

            {result.status === 'error' && (
              <div style={styles.errorCard}>
                {result.error}
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

// ================= STYLES =================
const styles = {
  page: { background: '#F1F5F9', minHeight: '100vh', fontFamily: 'Arial' },

  navbar: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: '15px 30px',
    background: '#111827',
    color: 'white'
  },

  brand: { fontWeight: 'bold', fontSize: 20 },

  navLinks: { display: 'flex', gap: 20 },

  link: { cursor: 'pointer', opacity: 0.7 },

  active: { opacity: 1, borderBottom: '2px solid #4F46E5' },

  userSection: {
    display: 'flex',
    alignItems: 'center',
    gap: 10
  },

  avatar: { fontSize: 20 },

  userId: { fontSize: 12 },
  userName: { fontSize: 14, opacity: 0.7 },

  logout: {
    marginLeft: 10,
    background: '#EF4444',
    color: 'white',
    border: 'none',
    padding: '6px 10px',
    borderRadius: 6
  },

  hero: { height: 220, position: 'relative' },

  heroImage: { width: '100%', height: '100%', objectFit: 'cover' },

  heroOverlay: {
    position: 'absolute',
    inset: 0,
    background: 'rgba(0,0,0,0.5)',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
